import { type FormEvent, useRef, useState } from 'react'

import { type Profile, updateProfile } from './api'

export function ProfileForm({ profile }: { profile: Profile }) {
  const [displayName, setDisplayName] = useState(profile.displayName)
  const [visibleName, setVisibleName] = useState(profile.displayName)
  const [saveFailed, setSaveFailed] = useState(false)
  const latestRequestId = useRef(0)
  const confirmed = useRef({ profile, requestId: 0 })

  async function handleSubmit(event: FormEvent) {
    event.preventDefault()
    const submittedName = displayName
    const requestId = ++latestRequestId.current

    setVisibleName(submittedName)
    setSaveFailed(false)

    try {
      const updatedProfile = await updateProfile(submittedName)
      if (updatedProfile.id !== profile.id) {
        throw new Error('Profile update returned a different profile')
      }

      if (requestId > confirmed.current.requestId) {
        confirmed.current = { profile: updatedProfile, requestId }
      }

      if (requestId === latestRequestId.current) {
        setVisibleName(updatedProfile.displayName)
      }
    } catch {
      if (requestId === latestRequestId.current) {
        setVisibleName(confirmed.current.profile.displayName)
        setSaveFailed(true)
      }
    }
  }

  return (
    <form onSubmit={handleSubmit}>
      <p aria-label="Current profile name">{visibleName}</p>
      <label>
        Display name
        <input
          value={displayName}
          onChange={(event) => setDisplayName(event.target.value)}
        />
      </label>
      <button>Save</button>
      {saveFailed && <p role="alert">Save failed. Please retry.</p>}
    </form>
  )
}

export type Profile = {
  id: string
  displayName: string
  version: number
}

export type ProfileUpdate = Pick<Profile, 'displayName'>

function isProfile(value: unknown): value is Profile {
  if (typeof value !== 'object' || value === null) return false

  const profile = value as Record<string, unknown>
  return (
    typeof profile.id === 'string' &&
    typeof profile.displayName === 'string' &&
    Number.isInteger(profile.version)
  )
}

export async function updateProfile(displayName: string): Promise<Profile> {
  const update: ProfileUpdate = { displayName }
  const response = await fetch('/api/profile', {
    method: 'PATCH',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(update),
  })

  if (!response.ok) {
    throw new Error(`Profile update failed with status ${response.status}`)
  }

  const profile: unknown = await response.json()
  if (!isProfile(profile)) {
    throw new Error('Profile update returned an invalid response')
  }

  return profile
}
